comments.suggestion_code:
$code = $_GET['code'] ?? null;

if ($code === null) {
    echo 'Code parameter is required';
    return;
}

$code = $_GET['code'] ?? null;

if (!is_numeric($code)) {
    echo 'Invalid code';
    return;
}

$code = (float)$code;

if ($code > 1) {
    echo 'Code is greater';
} else {
    echo 'Code is less';
}

